class Solution {
  public int[] concatenatedDivisibility(int[] nums, int k) {
    int n = nums.length;
    int[] a = nums.clone();
    java.util.Arrays.sort(a);
    int[] pow = new int[n];
    for (int i = 0; i < n; i++) {
      int p = 1;
      for (int t = a[i]; t > 0; t /= 10) p = p * 10 % k;
      pow[i] = p;
    }
    int full = (1 << n) - 1;
    boolean[][] good = new boolean[full + 1][k];
    good[full][0] = true;
    for (int mask = full - 1; mask >= 0; mask--) {
      for (int rem = 0; rem < k; rem++) {
        for (int i = 0; i < n; i++) {
          if ((mask >> i & 1) != 0) continue;
          int nr = (rem * pow[i] + a[i]) % k;
          if (good[mask | 1 << i][nr]) {
            good[mask][rem] = true;
            break;
          }
        }
      }
    }
    if (!good[0][0]) return new int[0];
    int[] res = new int[n];
    int mask = 0, rem = 0;
    for (int p = 0; p < n; p++) {
      for (int i = 0; i < n; i++) {
        if ((mask >> i & 1) != 0) continue;
        int nr = (rem * pow[i] + a[i]) % k;
        if (good[mask | 1 << i][nr]) {
          res[p] = a[i];
          mask |= 1 << i;
          rem = nr;
          break;
        }
      }
    }
    return res;
  }
}
